<script setup>
import { onMounted, reactive, ref } from 'vue';
import { api, dateLabel } from '../api';
import { loadWorkspace } from '../workspace';
import StatusBadge from '../components/StatusBadge.vue';
const profiles=ref([]), loading=ref(true), busy=ref(''), error=ref(''), success=ref(''), result=ref(null), selected=ref(''), defaultId=ref(''), keyConfigured=ref(false), formElement=ref(null);
const defaults=()=>({id:'',name:'',provider:'openai-compatible',base_url:'',model:'',api_key_env:'',api_key:'',timeout:120,max_tokens:8192,max_turns:12,max_requests:40,max_retries:2,stream:false,structured_output:'json_schema',strict_schema:false,supports_tools:true,supports_images:true,token_parameter:'max_tokens',default:false});
const form=reactive(defaults());
function edit(profile){selected.value=profile.id;Object.assign(form,defaults(),Object.fromEntries(Object.keys(defaults()).filter(key=>key in profile).map(key=>[key,profile[key]])),{api_key:'',default:profile.id===defaultId.value});keyConfigured.value=Boolean(profile.has_api_key||profile.api_key_configured||profile.has_key);result.value=null;error.value='';success.value='';}
function create(){selected.value='';Object.assign(form,defaults(),{default:!profiles.value.length});keyConfigured.value=false;result.value=null;error.value='';success.value='';}
async function load(){loading.value=true;error.value='';try{const data=await api.profiles();profiles.value=data.profiles||[];defaultId.value=data.default_profile_id||'';if(profiles.value.length)edit(profiles.value.find(p=>p.id===selected.value)||profiles.value.find(p=>p.id===defaultId.value)||profiles.value[0]);else create();}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function save(test=false){if(!formElement.value?.reportValidity())return;busy.value='save';error.value='';success.value='';result.value=null;try{const payload=Object.fromEntries(Object.keys(defaults()).map(key=>[key,form[key]]));for(const key of ['timeout','max_tokens','max_turns','max_requests','max_retries'])payload[key]=Number(payload[key]);if(!payload.id)delete payload.id;if(!payload.api_key)delete payload.api_key;const response=await api.saveProfile(payload);const profile=response.profile||response;form.api_key='';selected.value=profile.id;await load();success.value='模型配置已保存。';await loadWorkspace();if(test){busy.value='test';result.value=await api.testProfile(selected.value);if(!result.value.ok)success.value='';}}catch(e){if(busy.value==='test'){result.value={ok:false,error:e.message};success.value='';}else error.value=e.message;}finally{busy.value='';}}
onMounted(load);
</script>
<template>
  <section><div class="page-heading"><div><div class="eyebrow">MODEL CONNECTIONS</div><h1>连接你的模型服务</h1><p>评审直接通过 LLM API 执行。配置远端服务或本机模型地址，为每次运行选择合适的模型。</p></div><button class="button" :disabled="!!busy" @click="create">＋ 添加配置</button></div>
    <div v-if="error" class="notice error" role="alert">{{ error }}</div><div v-if="success" class="notice success" role="status">{{ success }}</div>
    <div v-if="loading" class="loading-state">正在加载模型配置</div>
    <div v-else class="model-layout"><aside class="section-card model-sidebar"><div class="section-heading"><h2>已保存配置</h2><span>{{ profiles.length }}</span></div><p v-if="!profiles.length" class="small-copy muted">还没有模型服务。填写右侧连接信息后保存。</p><button v-for="profile in profiles" :key="profile.id" class="profile-choice" :class="{selected:selected===profile.id}" :disabled="!!busy" @click="edit(profile)"><span><strong>{{ profile.name||profile.model }}</strong><small>{{ profile.model }}</small></span><StatusBadge v-if="profile.id===defaultId" tone="success">默认</StatusBadge></button><div class="model-note"><h3>本机与远端</h3><p>网页和材料管理运行在本机。使用远端模型时，参与分析的材料内容会通过配置的模型接口发送。</p><p>本机模型可填写本地 API 地址，是否支持图像、工具调用等能力取决于实际模型。</p></div></aside>
      <div><form ref="formElement" class="section-card" @submit.prevent="save(false)"><div class="section-heading"><h2>{{ selected?'编辑模型配置':'新增模型配置' }}</h2><StatusBadge tone="neutral">直接 API</StatusBadge></div><div class="form-grid"><div class="field"><label for="model-name">配置名称</label><input id="model-name" v-model="form.name" placeholder="例如：评审主模型" maxlength="100" :disabled="!!busy" required /></div><div class="field"><label for="model-provider">接口协议</label><select id="model-provider" v-model="form.provider" :disabled="!!busy"><option value="openai-compatible">OpenAI 兼容接口</option></select></div><div class="field span-2"><label for="model-base">服务地址（Base URL）</label><input id="model-base" v-model="form.base_url" type="url" placeholder="https://your-provider.example/v1" :disabled="!!busy" required /><span class="help">填写服务商的 API 根地址；本机模型也可使用 localhost 地址。</span></div><div class="field span-2"><label for="model-id">模型名称</label><input id="model-id" v-model="form.model" placeholder="填写服务支持的模型 ID" :disabled="!!busy" required /></div><div class="field span-2"><label for="model-key">API Key <span class="muted">（本机无鉴权服务可留空）</span></label><input id="model-key" v-model="form.api_key" type="password" autocomplete="new-password" :placeholder="keyConfigured?'已保存密钥，留空保留':'输入 API Key'" :disabled="!!busy" /><span class="help">密钥由本机后端保存；页面重新打开时不会回显。</span></div><div class="field span-2"><label for="model-key-env">或使用环境变量中的密钥</label><input id="model-key-env" v-model="form.api_key_env" placeholder="例如 SCHEMATIC_LLM_API_KEY" :disabled="!!busy" /><span class="help">填写环境变量名，后端从启动环境读取对应值。</span></div></div><details class="profile-advanced"><summary>调用与预算设置</summary><div class="form-grid"><div class="field"><label for="model-timeout">请求超时（秒）</label><input id="model-timeout" v-model="form.timeout" type="number" min="1" max="1200" required /></div><div class="field"><label for="model-tokens">单次最大输出 Token</label><input id="model-tokens" v-model="form.max_tokens" type="number" min="128" max="131072" required /></div><div class="field"><label for="model-turns">最大工具循环轮次</label><input id="model-turns" v-model="form.max_turns" type="number" min="1" max="100" required /></div><div class="field"><label for="model-requests">单任务最大请求次数</label><input id="model-requests" v-model="form.max_requests" type="number" min="1" max="500" required /></div><div class="field"><label for="model-retries">失败重试次数</label><input id="model-retries" v-model="form.max_retries" type="number" min="0" max="8" required /></div><div class="field"><label for="model-output">结构化输出方式</label><select id="model-output" v-model="form.structured_output"><option value="json_schema">JSON Schema</option><option value="json_object">JSON Object</option><option value="none">模型文本返回</option></select></div><div class="field span-2"><label for="model-token-parameter">输出预算参数</label><select id="model-token-parameter" v-model="form.token_parameter"><option value="max_tokens">max_tokens</option><option value="max_completion_tokens">max_completion_tokens</option></select><span class="help">按服务商文档选择兼容参数；能力开关应与实际模型支持保持一致。</span></div><label class="check-label"><input type="checkbox" v-model="form.supports_tools" />支持工具调用</label><label class="check-label"><input type="checkbox" v-model="form.supports_images" />支持图像输入</label><label class="check-label"><input type="checkbox" v-model="form.stream" />启用流式响应</label><label class="check-label"><input type="checkbox" v-model="form.strict_schema" />严格 JSON Schema</label></div></details><label class="check-label default-model"><input type="checkbox" v-model="form.default" :disabled="!!busy" />设为新运行的默认配置</label><div class="actions"><button class="button primary" :disabled="!!busy">{{ busy==='save'?'正在保存…':'保存配置' }}</button><button class="button" type="button" :disabled="!!busy||!form.base_url||!form.model||!form.name" @click="save(true)">{{ busy==='test'?'正在测试连接…':'保存并测试连接' }}</button></div><p class="inline-note">连接测试会向所选模型发起真实请求，用于验证接口和返回结果。</p></form>
      <div v-if="result" class="section-card" role="status"><div class="section-heading"><h2>连接测试结果</h2><StatusBadge :tone="result.ok?'success':'danger'">{{ result.ok?'测试通过':'测试未通过' }}</StatusBadge></div><p class="small-copy">{{ result.message||result.detail||result.error||(result.ok?'模型服务已返回有效响应。':'请检查接口地址、凭据和模型名称。') }}</p><dl class="metadata-list"><div v-if="result.model"><dt>响应模型</dt><dd>{{ result.model }}</dd></div><div v-if="result.latency_ms!=null"><dt>耗时</dt><dd>{{ result.latency_ms }} ms</dd></div><div v-if="result.tested_at"><dt>测试时间</dt><dd>{{ dateLabel(result.tested_at) }}</dd></div></dl><div v-if="result.capabilities" class="capability-list"><span v-for="(value,key) in result.capabilities" :key="key"><StatusBadge :tone="value===true?'success':value===false?'warning':'neutral'">{{ {tools:'工具调用',tool_calling:'工具调用',structured_output:'结构化输出',vision:'图像输入',streaming:'流式响应'}[key]||key }}：{{ value===true?'支持':value===false?'未通过':value }}</StatusBadge></span></div></div></div>
    </div>
  </section>
</template>
<style scoped>
.model-layout{display:grid;grid-template-columns:290px minmax(0,1fr);gap:24px;align-items:start}.profile-choice{display:flex;justify-content:space-between;align-items:center;gap:10px;width:100%;padding:13px 12px;margin-bottom:8px;border:1px solid transparent;border-radius:7px;background:#f6f8f6;text-align:left;color:var(--wb-ink)}.profile-choice.selected{border-color:#8fb6a4;background:#ecf6ef}.profile-choice strong{font-size:13px;display:block;font-weight:600}.profile-choice small{display:block;color:#698074;font-size:11px;line-height:1.6;overflow-wrap:anywhere;margin-top:4px}.model-note{border-top:1px solid var(--wb-border);margin-top:25px;padding-top:20px}.model-note h3{font-size:13px}.model-note p{font-size:12px;color:var(--wb-muted);line-height:1.8}.profile-advanced{margin-bottom:23px}.profile-advanced summary{cursor:pointer;color:#4f715f;font-size:13px;margin-bottom:20px}.default-model{margin-bottom:24px}.capability-list{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}@media(max-width:860px){.model-layout{grid-template-columns:1fr}.model-sidebar .model-note{display:none}.profile-choice{display:inline-flex;width:auto;margin-right:8px;max-width:100%}}
</style>
